    function arrangePages(anchor=null){if(!textViewport)return;if(appearance.mode==='page'){const flow=textViewport.querySelector('.page-flow');const width=textViewport.clientWidth;flow.style.columnWidth=width+'px';const step=width+48;pageCount=Math.max(1,Math.ceil((flow.scrollWidth+48)/step));if(anchor!==null){const el=flow.querySelector('[data-p="'+anchor+'"]');if(el){const x=el.getBoundingClientRect().left-textViewport.getBoundingClientRect().left+textViewport.scrollLeft;pageNo=Math.floor(x/step)}}pageNo=Math.max(0,Math.min(pageCount-1,pageNo));textViewport.scrollLeft=pageNo*step}else if(anchor!==null){const el=textViewport.querySelector('[data-p="'+anchor+'"]');if(el)textViewport.scrollTop=el.offsetTop-textViewport.offsetTop}observeReading()}
