      if(page==='shelf'){title.textContent='页间';main.innerHTML=`<div class="pad"><div class="eyebrow">Shared margins</div><h1>各读各的，<br>也一起读。</h1><div class="sub">有些话，适合留在页边。</div>${catalog.length?catalog.slice().sort((a,b)=>(b.lastRead||0)-(a.lastRead||0)).map(b=>`<button class="book" data-act="open" data-id="${esc(b.id)}"><span class="cover">${esc(b.title)}<small>页间 · 私人书架</small></span><span class="bookinfo"><h3>${esc(b.title)}</h3><span class="sub">${esc(display(characters.find(c=>c.id===b.characterId)))}<br>${b.confirmedEnd<0?'尚未开始':'已确认 '+Math.round((b.confirmedEnd+1)/b.paragraphCount*100)+'%'}</span>${b.unread?'<div style="margin-top:10px"><span class="pill">'+b.unread+' 条未读批注</span></div>':''}</span></button>`).join(''):'<div class="empty">书架还是空的。<br>导入一本 TXT，选一个人一起读。</div>'}<div class="section-actions" style="margin-top:24px"><button data-act="export">导出备份</button><button data-act="restore-backup">恢复备份</button></div><p class="sub footnote">书籍与记录保存在本设备的插件存储中。导出备份可以迁移设备；卸载插件前请先备份。</p></div>`;foot.innerHTML='<button class="solid widebtn" style="margin-top:0" data-act="import">导入 TXT 书籍</button>'}
      if(page==='import'){title.textContent='导入书籍';const d=importDraft;main.innerHTML=`<div class="pad"><label class="input-label">书名<input class="block" data-setting="import-title" value="${esc(d.title)}"></label><label class="line row">文件编码<select data-setting="encoding">${[['auto','自动识别'],['utf-8','UTF-8'],['gb18030','GB18030 / GBK'],['utf-16le','UTF-16 LE'],['utf-16be','UTF-16 BE'],['big5','Big5']].map(([v,t])=>`<option value="${v}" ${d.encoding===v?'selected':''}>${t}</option>`).join('')}</select></label><label class="line row">章节划分<select data-setting="chapterMode"><option value="detect" ${d.chapterMode==='detect'?'selected':''}>识别章节标题</option><option value="sections" ${d.chapterMode==='sections'?'selected':''}>按约 2400 字分小节</option></select></label><div class="line sub">识别编码：${esc(d.detected||'')}<br>${d.parsed?.paras.length||0} 段 · ${d.parsed?.chapters.length||0} 章／节 · ${d.parsed?.chars||0} 字${d.parsed?.autoSections?'<br>未识别到章节，长正文已自动划分阅读小节。':''}${d.error?'<p role="alert">'+esc(d.error)+'</p>':''}</div><h3 style="margin-top:24px">正文预览</h3><div class="import-preview">${esc((d.parsed?.paras||[]).slice(0,4).map(p=>p.text).join('\n\n'))}</div><h3 style="margin-top:24px">目录预览</h3><div class="sub">${(d.parsed?.chapters||[]).slice(0,15).map(c=>esc(c.title)).join('<br>')}</div><div class="notice-inline" style="margin-top:20px">先检查乱码与章节识别。没有章节的文本可按字数互动，或改用阅读小节。</div></div>`;foot.innerHTML='<button class="solid widebtn" style="margin-top:0" data-act="confirm-import" '+(d.error||!d.parsed?.paras.length?'disabled':'')+'>加入书架</button>'}
